def solve(n):
    if n == 2:
        return "NO"

    even_sum = 0
    odd_sum = 0

    # Generate the first half of the array with even numbers
    for i in range(1, n//2 + 1):
        even_sum += 2 * i
        yield 2 * i

    # Generate the second half of the array with odd numbers
    for i in range(1, n//2 + 1):
        odd_sum += 2 * i - 1
        yield 2 * i - 1

    # Adjust the last element of the second half to balance the sums
    diff = even_sum - odd_sum
    if diff % 2 != 0:
        return "NO"

    last_even = next(x for x in range(2, 10**9) if x % 2 == 0)
    last_odd = next(x for x in range(1, 10**9) if x % 2 != 0)

    if abs(last_even - last_odd) == diff // 2:
        return "NO"

    if even_sum > odd_sum:
        yield last_odd - diff // 2
    else:
        yield last_even + diff // 2

